uint8_t wdrv_map_to_ipc_chnl(uint8_t channel)
{
    switch(channel)
    {
        case TX_BK_CMD_DATA:
            return IPC_CMD;

        case TX_CEVA_CMD_DATA:
            return IPC_CMD;

        case TX_MSDU_DATA:
            return IPC_DATA;

        case TX_MPDU_DATA:
            return IPC_DATA;
        default:
            BK_ASSERT(0);
    }
    return 0XFF;
}


