/****************************************************************************
 * Name: agent_camera_set_format
 *
 * Description:
 *   tool_camera.c's format step, unchanged: ask for V4L2_PIX_FMT_JPEG and,
 *   if that is refused, ask for V4L2_PIX_FMT_ENTROPY.  A refusal of both is
 *   reported with the geometry that was refused, because on this board the
 *   geometry -- not the format -- is the usual reason.
 *
 ****************************************************************************/

static int agent_camera_set_format(int fd, int width, int height,
                                  uint32_t *out_fmt)
{
  struct v4l2_format fmt;

  memset(&fmt, 0, sizeof(fmt));
  fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width       = width;
  fmt.fmt.pix.height      = height;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.sizeimage   = CAM_BUF_SIZE;
  fmt.fmt.pix.field       = V4L2_FIELD_NONE;

  if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) == 0)
    {
      *out_fmt = V4L2_PIX_FMT_JPEG;
      return OK;
    }

  printf("agent_camera: S_FMT JPEG %dx%d failed: %d\n",
         width, height, errno);

  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_ENTROPY;

  if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) == 0)
    {
      *out_fmt = V4L2_PIX_FMT_ENTROPY;
      return OK;
    }

  printf("agent_camera: S_FMT ENTROPY %dx%d failed: %d\n",
         width, height, errno);
  return -errno;
}

