/****************************************************************************
 * Name: agent_camera_check_jpeg
 *
 * Description:
 *   Reports whether the frame looks like a JPEG: SOI (FFD8) at the front,
 *   EOI (FFD9) at the end.  A truncated frame is the failure this catches
 *   -- the encoder writes through a DMA channel and a short frame is the
 *   documented symptom of a chunk being lost (see the jpeg_short counter in
 *   bk7258_camera_imgdata.c), which byte-count alone would not reveal.
 *
 ****************************************************************************/

static void agent_camera_check_jpeg(const uint8_t *data, size_t len)
{
  bool soi;
  bool eoi;

  if (len < 4)
    {
      printf("agent_camera: frame too short to inspect (%zu bytes)\n", len);
      return;
    }

  soi = data[0] == 0xff && data[1] == 0xd8;
  eoi = data[len - 2] == 0xff && data[len - 1] == 0xd9;

  printf("agent_camera: markers SOI=%s EOI=%s "
         "head=%02x %02x tail=%02x %02x\n",
         soi ? "yes" : "NO", eoi ? "yes" : "NO",
         data[0], data[1], data[len - 2], data[len - 1]);

  if (!soi || !eoi)
    {
      printf("agent_camera: NOT a complete JPEG -- a Vision LLM would "
             "reject this frame\n");
    }
}

