/****************************************************************************
 * bk7258_jpeg_enc_write_header()
 *
 * These are the tests that would have caught a transcription error in the
 * standard Huffman tables on the desktop instead of costing a flash cycle:
 * one of them checks that every emitted DHT segment's bit counts sum to the
 * number of symbols that follow, which is exactly the invariant a mistyped
 * table breaks (and libjpeg rejects with "Bogus Huffman table definition").
 ****************************************************************************/

/* Builds a stand-in for what the encoder puts in the buffer: SOI, APP0,
 * SOF0, two DQT, three DHT, three 0xFF fill bytes before one of the markers
 * (the block does that), then entropy data.  Contents of the segments do not
 * matter here beyond their lengths -- what is under test is the rewrite.
 */

static size_t build_fake_bitstream(uint8_t *buf, size_t pad,
                                   size_t entropy_bytes)
{
  size_t i = pad;
  size_t k;

  buf[i++] = 0xff; buf[i++] = 0xd8;                    /* SOI */

  buf[i++] = 0xff; buf[i++] = 0xe0;                    /* APP0, len 16 */
  buf[i++] = 0x00; buf[i++] = 0x10;
  for (k = 0; k < 14; k++) buf[i++] = 0x00;

  buf[i++] = 0xff; buf[i++] = 0xc0;                    /* SOF0, len 17 */
  buf[i++] = 0x00; buf[i++] = 0x11;
  buf[i++] = 0x08;
  buf[i++] = 0x01; buf[i++] = 0xe0;                    /* height 480 */
  buf[i++] = 0x01; buf[i++] = 0xe0;                    /* width 480 */
  buf[i++] = 0x03;
  buf[i++] = 0x01; buf[i++] = 0x21; buf[i++] = 0x00;
  buf[i++] = 0x02; buf[i++] = 0x11; buf[i++] = 0x01;
  buf[i++] = 0x03; buf[i++] = 0x11; buf[i++] = 0x01;

  for (k = 0; k < 2; k++)                              /* DQT x2, len 67 */
    {
      buf[i++] = 0xff; buf[i++] = 0xdb;
      buf[i++] = 0x00; buf[i++] = 0x43;
      buf[i++] = (uint8_t)k;
      for (size_t q = 0; q < 64; q++) buf[i++] = 0x10;
    }

  /* Three fill bytes ahead of this marker, as the hardware emits. */

  buf[i++] = 0xff; buf[i++] = 0xff; buf[i++] = 0xff;

  buf[i++] = 0xff; buf[i++] = 0xc4;                    /* DHT, len 31 */
  buf[i++] = 0x00; buf[i++] = 0x1f;
  for (k = 0; k < 29; k++) buf[i++] = 0x00;

  buf[i++] = 0xff; buf[i++] = 0xc4;                    /* DHT, len 31 */
  buf[i++] = 0x00; buf[i++] = 0x1f;
  for (k = 0; k < 29; k++) buf[i++] = 0x00;

  buf[i++] = 0xff; buf[i++] = 0xc4;                    /* DHT, len 181 */
  buf[i++] = 0x00; buf[i++] = 0xb5;
  for (k = 0; k < 179; k++) buf[i++] = 0x00;

  /* Entropy data: a recognisable pattern so the test can prove it was not
   * moved or overwritten.
   */

  for (k = 0; k < entropy_bytes; k++)
    {
      buf[i + k] = (uint8_t)(0x40u + (k % 0x30u));
    }

  return i;   /* entropy offset */
}

static void test_write_header_layout(void)
{
  static uint8_t buf[8192];
  const size_t pad = BK7258_JPEG_ENC_PAD;
  const size_t entropy_bytes = 512;
  size_t expect;
  size_t got;
  size_t i;
  int nseg[256];
  int order[16];
  int norder = 0;

  memset(buf, 0, sizeof(buf));
  memset(nseg, 0, sizeof(nseg));

  expect = build_fake_bitstream(buf, pad, entropy_bytes);
  got = bk7258_jpeg_enc_write_header(buf, pad);

  CHECK(got == expect,
        "entropy offset: expected %zu, got %zu", expect, got);

  CHECK(buf[0] == 0xff && buf[1] == 0xd8,
        "rewritten stream must start with SOI, got %02x %02x",
        buf[0], buf[1]);

  /* Walk the rewritten header and record the segment order. */

  i = 2;
  while (i + 3 < got)
    {
      uint8_t marker;
      size_t seglen;

      CHECK(buf[i] == 0xff, "expected a marker at %zu, got %02x", i, buf[i]);
      if (buf[i] != 0xff)
        {
          return;
        }

      while (buf[i + 1] == 0xff)
        {
          i++;
        }

      marker = buf[i + 1];
      seglen = ((size_t)buf[i + 2] << 8) | buf[i + 3];
      nseg[marker]++;
      if (norder < 16)
        {
          order[norder++] = marker;
        }

      /* Every DHT must be self-consistent: the 16 bit-length counts have to
       * add up to the number of symbols in the rest of the segment.  This is
       * the check that catches a mistyped table.
       */

      if (marker == 0xc4)
        {
          size_t counts = 0;
          size_t k;

          for (k = 0; k < 16; k++)
            {
              counts += buf[i + 5 + k];
            }

          CHECK(counts == seglen - 19,
                "DHT at %zu: counts sum %zu but %zu symbols follow",
                i, counts, seglen - 19);
        }

      if (marker == 0xda)
        {
          CHECK(i + 2 + seglen == got,
                "SOS must end exactly where entropy starts: %zu vs %zu",
                i + 2 + seglen, got);
          break;
        }

      i += 2 + seglen;
    }

  CHECK(nseg[0xc0] == 1, "expected exactly one SOF0, got %d", nseg[0xc0]);
  CHECK(nseg[0xdb] == 2, "expected two DQT, got %d", nseg[0xdb]);
  CHECK(nseg[0xc4] == 4, "expected four DHT, got %d", nseg[0xc4]);
  CHECK(nseg[0xfe] == 1, "expected one COM, got %d", nseg[0xfe]);
  CHECK(nseg[0xda] == 1, "expected one SOS, got %d", nseg[0xda]);
  CHECK(nseg[0xe0] == 0, "APP0 should not be carried over, got %d",
        nseg[0xe0]);

  /* DHT tables must cover both DC and AC for both luma and chroma, which is
   * what the hardware fails to do (it omits chroma AC).
   */

  CHECK(norder >= 8, "expected at least 8 segments, got %d", norder);

  /* Entropy data must be untouched. */

  for (i = 0; i < entropy_bytes; i++)
    {
      if (buf[got + i] != (uint8_t)(0x40u + (i % 0x30u)))
        {
          CHECK(false, "entropy byte %zu was modified: %02x",
                i, buf[got + i]);
          break;
        }
    }
}

static void test_write_header_dht_ids_cover_all_four(void)
{
  static uint8_t buf[8192];
  const size_t pad = BK7258_JPEG_ENC_PAD;
  bool seen[4] = { false, false, false, false };
  size_t got;
  size_t i;

  memset(buf, 0, sizeof(buf));
  build_fake_bitstream(buf, pad, 128);
  got = bk7258_jpeg_enc_write_header(buf, pad);

  i = 2;
  while (i + 3 < got)
    {
      uint8_t marker;
      size_t seglen;

      while (buf[i + 1] == 0xff)
        {
          i++;
        }

      marker = buf[i + 1];
      seglen = ((size_t)buf[i + 2] << 8) | buf[i + 3];

      if (marker == 0xc4)
        {
          uint8_t tc = buf[i + 4] >> 4;
          uint8_t th = buf[i + 4] & 0x0f;

          CHECK(tc <= 1 && th <= 1, "DHT id out of range: Tc=%u Th=%u",
                tc, th);
          if (tc <= 1 && th <= 1)
            {
              seen[tc * 2 + th] = true;
            }
        }

      if (marker == 0xda)
        {
          break;
        }

      i += 2 + seglen;
    }

  CHECK(seen[0], "missing DC table Th=0");
  CHECK(seen[1], "missing DC table Th=1");
  CHECK(seen[2], "missing AC table Th=0");
  CHECK(seen[3], "missing AC table Th=1 (the one the hardware omits)");
}

static void test_write_header_rejects_bad_input(void)
{
  static uint8_t buf[8192];

  memset(buf, 0, sizeof(buf));
  CHECK(bk7258_jpeg_enc_write_header(NULL, BK7258_JPEG_ENC_PAD) == 0,
        "NULL buffer must be refused");

  /* No SOI where the bitstream should start. */

  memset(buf, 0x5a, sizeof(buf));
  CHECK(bk7258_jpeg_enc_write_header(buf, BK7258_JPEG_ENC_PAD) == 0,
        "a stream without SOI must be refused");

  /* A pad too small to fit the replacement header: the hardware header is
   * ~429 bytes and the replacement 605, so with no pad there is no room.
   */

  memset(buf, 0, sizeof(buf));
  build_fake_bitstream(buf, 0, 128);
  CHECK(bk7258_jpeg_enc_write_header(buf, 0) == 0,
        "pad=0 leaves no room for the longer header and must be refused");
}

