/****************************************************************************
 * BK7258 UART Ctrl-C probe
 *
 * Ctrl-C does not stop a foreground application on this board.  This program
 * narrows down why, by reporting each precondition separately instead of
 * just waiting for a signal that may never come.
 *
 * For 0x03 to become a SIGINT, drivers/serial/serial.c's uart_check_special()
 * needs three things at once:
 *
 *   1. dev->tc_lflag & ISIG      -- set by uart_register() when the device
 *                                   declares isconsole (ours does)
 *   2. dev->pid > 0              -- set ONLY by the TIOCSCTTY ioctl, and it
 *                                   refuses to change once set (a second
 *                                   TIOCSCTTY returns -EINVAL)
 *   3. the byte equals CONFIG_TTY_SIGINT_CHAR (0x03)
 *
 * NSH is supposed to do 2 for us: nsh_builtin.c registers the child pid with
 * TIOCSCTTY before waitpid(), but only if vtbl->isctty.  So this probe calls
 * TIOCSCTTY itself and prints what happens:
 *
 *   returns 0        -> nobody had claimed it, i.e. NSH did NOT (isctty was
 *                       false, or the ioctl failed).  Root cause found.
 *   returns -EINVAL  -> somebody already owns it.  Then the question becomes
 *                       *who*, since it must be this task for SIGINT to
 *                       arrive here.
 *
 * Either way it then waits for SIGINT with a handler installed, so the test
 * does not depend on CONFIG_SIG_DEFAULT.
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <termios.h>
#include <unistd.h>

static volatile sig_atomic_t g_sigint_received;

static void ctrlc_test_handler(int signo)
{
  (void)signo;
  g_sigint_received = 1;
}

int main(int argc, char *argv[])
{
  struct sigaction act;
  struct termios tio;
  int ret;
  int i;

  act.sa_handler = ctrlc_test_handler;
  sigemptyset(&act.sa_mask);
  act.sa_flags = 0;

  if (sigaction(SIGINT, &act, NULL) < 0)
    {
      perror("sigaction");
      return 1;
    }

  printf("ctrlc_test: pid=%d\n", (int)getpid());

  /* Precondition 1: is ISIG actually on for this console? */

  if (tcgetattr(STDIN_FILENO, &tio) == 0)
    {
      printf("ctrlc_test: tcgetattr ok, ISIG=%s lflag=0x%lx\n",
             (tio.c_lflag & ISIG) ? "on" : "OFF",
             (unsigned long)tio.c_lflag);
    }
  else
    {
      printf("ctrlc_test: tcgetattr failed: %d\n", errno);
    }

  /* Precondition 2: who owns the controlling terminal? */

  ret = ioctl(STDIN_FILENO, TIOCSCTTY, (unsigned long)getpid());
  if (ret == 0)
    {
      printf("ctrlc_test: TIOCSCTTY ok -- it was UNCLAIMED, so NSH did not "
             "set it\n");
    }
  else
    {
      printf("ctrlc_test: TIOCSCTTY failed: %d (EINVAL means already "
             "claimed)\n", errno);
    }

  printf("ctrlc_test: press Ctrl-C now (waiting 15s)\n");

  for (i = 0; i < 15 && !g_sigint_received; i++)
    {
      sleep(1);
    }

  if (g_sigint_received)
    {
      printf("ctrlc_test: SIGINT RECEIVED\n");
      return 0;
    }

  printf("ctrlc_test: NO SIGINT after 15s\n");
  return 1;
}

